  /// Fast Lookup Maps for the Jarvis Chatbot and Portal
  static final Map<String, StudentModel> byRollNumber = {
    for (var s in allStudents) s.rollNumber: s,
  };

  static final Map<String, List<StudentModel>> bySection = {
    for (var s in allStudents)
      '${s.year}-${s.section}': allStudents.where((x) => x.year == s.year && x.section == s.section).toList(),
  };

  /// Query students by partial name, roll number, or section
  static List<StudentModel> search(String query) {
    final q = query.toLowerCase().trim();
    if (q.isEmpty) return allStudents;
    return allStudents.where((s) {
      return s.name.toLowerCase().contains(q) ||
          s.rollNumber.toLowerCase().contains(q) ||
          s.section.toLowerCase() == q ||
          '${s.romanYear} ${s.section}'.toLowerCase().contains(q);
    }).toList();
  }
}
